svg.script:
(function () {
  function init() {
    var doc = document;
    var svg = doc.getElementById('svg1') || doc.querySelector('svg');
    if (!svg) return;
    var tip=doc.getElementById('site-tooltip'), tipRect=doc.getElementById('tooltip-bg'), tipShadow=doc.getElementById('tooltip-shadow'), tipAccent=doc.getElementById('tooltip-accent');
    var nameText=doc.getElementById('tooltip-site-name'), telemetryText=doc.getElementById('tooltip-telemetry'), assetText=doc.getElementById('tooltip-asset');
    var hover=doc.getElementById('hover-tooltip'), hoverRect=doc.getElementById('hover-tooltip-bg'), hoverName=doc.getElementById('hover-tooltip-site-name');
    var selected=doc.getElementById('selected-site-indicator'), legend=doc.getElementById('status-legend');
    var siteSelector='.site-marker, .Site, circle[id^="site-"], ellipse[id^="site-"], rect[id^="site-"], path[id^="site-"], g[id^="site-"]';
    function inLegend(t){return !!(legend&&t&&(t===legend||legend.contains(t)));}
    function findSite(t){if(inLegend(t)||!t||!t.closest)return null;var e=t.closest(siteSelector);if(!e||e===tip||e===hover||(tip&&tip.contains(e))||(hover&&hover.contains(e)))return null;return e;}
    function makeClickable(){doc.querySelectorAll(siteSelector).forEach(function(s){if(s===tip||s===hover||(tip&&tip.contains(s))||(hover&&hover.contains(s)))return;s.style.cursor='pointer';s.style.pointerEvents='all';s.style.outline='none';s.setAttribute('Interconnect','Selected');});}
    makeClickable(); if(tip)tip.style.pointerEvents='none'; if(hover)hover.style.pointerEvents='none';
    function point(evt){var p=svg.createSVGPoint();p.x=evt.clientX||0;p.y=evt.clientY||0;var c=svg.getScreenCTM();return c?p.matrixTransform(c.inverse()):p;}
    function anchor(evt,e){if(evt&&typeof evt.clientX==='number')return point(evt);var b=e.getBBox();return{x:b.x+b.width/2,y:b.y+b.height/2};}
    function position(group,rect,evt,e){if(!group||!rect)return;var p=anchor(evt,e),w=parseFloat(rect.getAttribute('width'))||500,h=parseFloat(rect.getAttribute('height'))||100,vb=svg.viewBox.baseVal,gap=Math.max(vb.width/120,18),x=p.x+gap,y=p.y-h-gap;if(x+w>vb.x+vb.width)x=p.x-w-gap;if(y<vb.y)y=p.y+gap;x=Math.max(vb.x,Math.min(x,vb.x+vb.width-w));y=Math.max(vb.y,Math.min(y,vb.y+vb.height-h));group.setAttribute('transform','translate('+x+','+y+')');}
    function showHover(e,evt){if(!hover||!hoverRect||!hoverName)return;var n=e.getAttribute('data-site-name')||e.getAttribute('data-asset-id')||e.id||'Unknown site';hoverName.textContent=n;var fs=parseFloat(hoverName.getAttribute('font-size'))||42;hoverRect.setAttribute('width',Math.max(360,Math.min(950,fs*(2+n.length*.62))));hover.setAttribute('visibility','visible');position(hover,hoverRect,evt,e);}
    function hideHover(){if(hover)hover.setAttribute('visibility','hidden');}
    function updateSelected(e){if(!selected)return;selected.setAttribute('data-id-selected',e.id||'');selected.setAttribute('data-telemetry-id-selected',e.getAttribute('data-telemetry-id')||'');selected.setAttribute('data-status-selected',e.getAttribute('data-status')||'');selected.setAttribute('data-asset-id-selected',e.getAttribute('data-asset-id')||'');selected.setAttribute('data-site-name-selected',e.getAttribute('data-site-name')||'');var b=e.getBBox();selected.setAttribute('cx',b.x+b.width/2);selected.setAttribute('cy',b.y+b.height/2);selected.setAttribute('visibility','visible');}
    function showPopup(e,evt){if(!tip||!tipRect||!nameText||!telemetryText||!assetText)return;var n=e.getAttribute('data-site-name')||e.getAttribute('data-asset-id')||e.id||'Unknown site',t=e.getAttribute('data-telemetry-id')||'N/A',a=e.getAttribute('data-asset-id')||'N/A';nameText.textContent=n;telemetryText.textContent='Telemetry ID: '+t;assetText.textContent='Asset ID: '+a;var fs=parseFloat(nameText.getAttribute('font-size'))||44,longest=Math.max(n.length,telemetryText.textContent.length,assetText.textContent.length),w=Math.max(840,Math.min(1200,fs*(2+longest*.62)));tipRect.setAttribute('width',w);if(tipShadow)tipShadow.setAttribute('width',w);if(tipAccent)tipAccent.setAttribute('height',tipRect.getAttribute('height'));tip.setAttribute('visibility','visible');position(tip,tipRect,evt,e);updateSelected(e);}
    function clearPopup(){if(tip)tip.setAttribute('visibility','hidden');if(selected)selected.setAttribute('visibility','hidden');}
    svg.addEventListener('pointermove',function(evt){var s=findSite(evt.target);s?showHover(s,evt):hideHover();},true);
    svg.addEventListener('pointerleave',hideHover,true);
    svg.addEventListener('click',function(evt){if(inLegend(evt.target)){hideHover();evt.preventDefault();evt.stopImmediatePropagation();return;}var s=findSite(evt.target);if(s){showPopup(s,evt);}else{clearPopup();hideHover();} /* do not stop propagation: Asset Intellect reads Interconnect/data-telemetry-id */},true);
    svg.addEventListener('keydown',function(evt){if(evt.key==='Enter'||evt.key===' '){var s=findSite(evt.target);if(s)showPopup(s,evt);}},true);
    if(window.MutationObserver)new MutationObserver(makeClickable).observe(svg,{childList:true,subtree:true,attributes:true,attributeFilter:['id','class']});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
